select sum(p.id) over (order by p.id rows between unbounded preceding and unbounded following exclude current row) as without_row, sum(p.id) over (order by p.user_id range between current row and current row exclude group) as without_group, sum(p.id) over (order by p.user_id range between current row and current row exclude ties) as without_ties, sum(p.id) over (order by p.id range unbounded preceding exclude no others) as with_all from posts p
